<?php require_once 'functions.php'; require_login(); $id=(int)($_GET['id']??0);$s=$koneksi->prepare('SELECT p.*,pay.metode,pay.status pay_status,pay.reference,pay.paid_at FROM pesanan p LEFT JOIN pembayaran pay ON pay.id_pesanan=p.id_pesanan WHERE p.id_pesanan=? AND p.id_user=?');$s->bind_param('ii',$id,$_SESSION['user']['id_user']);$s->execute();$o=$s->get_result()->fetch_assoc();if(!$o)redirect('pesanan.php');if($_SERVER['REQUEST_METHOD']==='POST'&&$o['pay_status']==='pending'){check_csrf();$koneksi->begin_transaction();try{$u=$koneksi->prepare("UPDATE pembayaran SET status='paid',paid_at=NOW() WHERE id_pesanan=? AND status='pending'");$u->bind_param('i',$id);$u->execute();$u2=$koneksi->prepare("UPDATE pesanan SET status='paid' WHERE id_pesanan=? AND status='pending'");$u2->bind_param('i',$id);$u2->execute();$koneksi->commit();flash('success','Pembayaran sandbox berhasil.');redirect('pesanan.php?id='.$id);}catch(Throwable $e){$koneksi->rollback();flash('error','Pembayaran gagal diproses.');redirect('pembayaran.php?id='.$id);}}$title='Pembayaran';include 'header.php'; ?>
<div class="container narrow"><div class="panel center"><span class="pill">PAYMENT GATEWAY SANDBOX</span><h1><?=e($o['reference'])?></h1><div class="payment-amount"><?=rupiah($o['total'])?></div><p>Metode: <b><?=e($o['metode'])?></b></p><?php if($o['pay_status']==='pending'): ?><div class="sandbox-box"><b>Mode Demo</b><p>Tombol di bawah mensimulasikan callback sukses dari payment gateway. Tidak ada uang sungguhan yang ditagihkan.</p></div><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><button class="btn full">✓ Simulasikan Pembayaran Berhasil</button></form><?php else:?><div class="alert success">Pembayaran berhasil pada <?=e($o['paid_at'])?>.</div><a class="btn" href="pesanan.php?id=<?=$id?>">Lihat Pesanan</a><?php endif;?></div></div><?php include 'footer.php'; ?>
